#!/usr/bin/env python3
"""Execute legacy128-bit PACKUSWB through Rosetta, all signed-word values per lane."""
import hashlib,json,pathlib,subprocess
R=pathlib.Path(__file__).resolve().parents[1];out=R/'generated/sse/legacy-packuswb-reference';out.mkdir(exist_ok=True);sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();source=R/'tests/legacy_packuswb_oracle.c';exe=out/'reference';sdk=subprocess.check_output(['xcrun','--sdk','macosx','--show-sdk-path'],text=True).strip();cmd=['clang','-target','x86_64-apple-macos12','-isysroot',sdk,'-std=c11','-O2','-mavx','-mno-red-zone','-Wall','-Wextra','-Werror',str(source),'-o',str(exe)];subprocess.run(cmd,check=True);run=subprocess.run([str(exe)],capture_output=True,text=True,timeout=60);assert not run.returncode and run.stdout.startswith('PASS:') and not run.stderr,(run.returncode,run.stdout,run.stderr);(out/'run.log').write_text(run.stdout);assembly=subprocess.check_output(['otool','-tvV',str(exe)],text=True);(out/'disassembly.txt').write_text(assembly);assert assembly.count('\tpackuswb\t')==2 and 'vpackuswb' not in assembly;report={'pass':True,'cases':131072,'source_sha256':{str(p.relative_to(R)):sha(p) for p in [source,pathlib.Path(__file__).resolve()]},'binary_sha256':sha(exe),'compile_command':cmd,'output':run.stdout.strip(),'scope':'Canonical legacy PACKUSWB REG and alignedMEM128 under Rosetta, all65536 signed-word values in each lane. LowXMM signed-word saturation/packing result, upperYMM/source preservation and all1024 masked MXCSR configurations and arithmeticflag patterns. A standalone Rosetta probe loading0 reads back1F80; this reference is limited to masked configurations. Unmasked preservation is separately tested by emitted ARM. Not physicalIntel/guestfault/fullDLL/gameplay proof.'};(out/'result.json').write_text(json.dumps(report,indent=2)+'\n');print(run.stdout.strip())
